add_filter( 'wc_get_template', 'perfectpixel_ignore_theme_wc_templates', 9999, 5 );

function perfectpixel_ignore_theme_wc_templates( $located, $template_name, $args, $template_path, $default_path ) {
	// Template names the theme may still override, e.g. 'single-product/title.php'.
	$allowed = array();

	if ( in_array( $template_name, $allowed, true ) ) {
		return $located;
	}
	$themes = array_unique( array( wp_normalize_path( get_stylesheet_directory() ), wp_normalize_path( get_template_directory() ) ) );
	foreach ( $themes as $dir ) {
		if ( 0 === strpos( wp_normalize_path( $located ), trailingslashit( $dir ) ) ) {
			$plugin_template = trailingslashit( $default_path ? $default_path : WC()->plugin_path() . '/templates/' ) . $template_name;
			return file_exists( $plugin_template ) ? $plugin_template : $located;
		}
	}
	return $located;
}
